solution.diffie_hellman.zig:
const std = @import("std");

/// Inject an RNG so callers choose and seed their randomness explicitly.
pub fn privateKey(random: std.Random, prime: u64) !u64 {
    if (prime <= 2) return error.InvalidPrime;
    return random.intRangeAtMost(u64, 2, prime - 1);
}
pub fn publicKey(prime: u64, generator: u64, private: u64) !u64 {
    return power(prime, generator, private);
}
pub fn secret(prime: u64, public: u64, private: u64) !u64 {
    return power(prime, public, private);
}
fn power(prime: u64, base: u64, exponent: u64) !u64 {
    if (prime < 2) return error.InvalidPrime;
    var result: u64 = 1;
    var factor = base % prime;
    var n = exponent;
    while (n > 0) : (n >>= 1) {
        if (n & 1 == 1) result = @intCast(@as(u128, result) * factor % prime);
        factor = @intCast(@as(u128, factor) * factor % prime);
    }
    return result;
}

tests.test_diffie_hellman.zig:
const std = @import("std");
const t = std.testing;
const a = t.allocator;
const m = @import("diffie_hellman.zig");

test "private keys, public keys and shared secret" {
    var rng = std.Random.DefaultPrng.init(1234);
    var seen = std.AutoHashMap(u64, void).init(a);
    defer seen.deinit();
    for (0..20) |_| {
        const key = try m.privateKey(rng.random(), 2147483647);
        try t.expect(key > 1 and key < 2147483647);
        try t.expect(!seen.contains(key));
        try seen.put(key, {});
    }
    try t.expectError(error.InvalidPrime, m.privateKey(rng.random(), 2));
    try t.expectEqual(@as(u64, 8), try m.publicKey(23, 5, 6));
    try t.expectEqual(@as(u64, 19), try m.publicKey(23, 5, 15));
    try t.expectEqual(@as(u64, 2), try m.secret(23, 19, 6));
    const alice = try m.privateKey(rng.random(), 23);
    const bob = try m.privateKey(rng.random(), 23);
    try t.expectEqual(try m.secret(23, try m.publicKey(23, 5, alice), bob), try m.secret(23, try m.publicKey(23, 5, bob), alice));
    try t.expectEqual(@as(u64, 1), try m.publicKey(18446744073709551557, 18446744073709551556, 2));
}
